import Foundation

/// Marks events generated by this app so the direction filter never transforms them
/// twice. This is a recursion guard, not a security identity.
public enum SyntheticEventMarker {
    /// ASCII "MSFSCRL1".
    public static let autoScroll: Int64 = 0x4D53_4653_4352_4C31
    /// ASCII "MSFSMTH1" — reserved for a future smooth-wheel feature.
    public static let smoothWheel: Int64 = 0x4D53_4653_4D54_4831

    public static func isOurs(_ userData: Int64) -> Bool {
        userData == autoScroll || userData == smoothWheel
    }
}
